export function applyWorkPlink(poets: Poet[]): number {
  const idx = new Map<string, Poet>();
  for (const p of poets) idx.set(p.id, p);
  let n = 0;
  for (const pl of PLINK) {
    const p = idx.get(pl.poetId);
    if (!p) continue;
    // 定位 -wa 作品（按 poetId + title）
    let found: { node: LifeNode; work: Work } | null = null;
    outer: for (const node of p.nodes) {
      for (const w of node.works) {
        if (/\-wa\d+$/.test(w.id) && w.title === pl.title) { found = { node, work: w }; break outer; }
      }
    }
    if (!found) continue;
    const { node, work } = found;
    // 仅年份回填
    if (pl.year != null && !pl.place) {
      work.year = pl.year;
      work.yearLabel = pl.yearLabel ?? undefined; // null → 清空原 errors label
      n++; continue;
    }
    if (!pl.place || pl.lng == null || pl.lat == null) continue; // 只有地点没坐标：无法造点，跳过
    // 复用已有节点：按 place 或 modernPlace 匹配
    let dest = p.nodes.find((nd) => nd.place === pl.place || (pl.modern != null && nd.modernPlace === pl.modern));
    if (!dest) {
      const lng = pl.lng!; const lat = pl.lat!;
      dest = p.nodes.find((nd) => Math.abs(nd.lng - lng) < 0.06 && Math.abs(nd.lat - lat) < 0.06);
      if (!dest) {
        let seq = p.nodes.length + 1;
        let id = `${p.id}-pl${seq}`;
        while (p.nodes.some((nd) => nd.id === id)) { seq += 1; id = `${p.id}-pl${seq}`; }
        dest = {
          id,
          year: pl.year ?? node.year,
          place: pl.place,
          modernPlace: pl.modern ?? pl.place,
          lng: pl.lng,
          lat: pl.lat,
          eventType: (pl.eventType as EventType) ?? 'office',
          event: pl.event ? pl.event : `辞典补录《${work.title}》创作地。`,
          works: [],
          note: `地点/系年由辞典赏析回填（confidence ${pl.confidence}）`,
        };
        p.nodes.push(dest);
      }
    }
    // 改挂：从原节点移除，挂到目标节点（若已是目标则只补年份/背景）
    if (dest !== node) {
      const ri = node.works.findIndex((w) => w.id === work.id);
      if (ri >= 0) node.works.splice(ri, 1);
      dest.works.push(work);
      work.placeId = dest.id;
    }
    if (pl.year != null) { work.year = pl.year; work.yearLabel = pl.yearLabel ?? undefined; }
    if (work.background && work.background.includes('待考')) {
      work.background = work.background.replace(/系年与地点待考[。.]?/, '系年与地点据辞典赏析回填');
    }
    n++;
  }
  return n;
}
